import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import type { PrimitiveProps } from "../primitives";

const PRIMARY = "#05B8E6";
const DEEP = "#0A8FC0";
const LIGHT = "#FFFFFF";

// iad pictogram language: rounded pills and dots at the 11° slash angle,
// in tones of the blue, drifting slowly over a solid iad blue field. Positions are on a 1080×1920 stage.
const SHAPES = [
  { x: -140, y: 140, w: 520, h: 128, c: DEEP, o: 0.55, a: 36, b: 60, period: 12 },
  { x: 300, y: 300, w: 128, h: 128, c: LIGHT, o: 0.14, a: -44, b: 52, period: 14 },
  { x: 840, y: 660, w: 400, h: 88, c: LIGHT, o: 0.1, a: -44, b: 52, period: 14 },
  { x: 680, y: 1500, w: 600, h: 144, c: DEEP, o: 0.55, a: 36, b: -60, period: 12 },
  { x: -80, y: 1320, w: 300, h: 80, c: LIGHT, o: 0.1, a: 36, b: -60, period: 12 },
  { x: 900, y: 1340, w: 52, h: 52, c: LIGHT, o: 0.18, a: 24, b: 36, period: 9 },
  { x: 160, y: 560, w: 28, h: 28, c: LIGHT, o: 0.18, a: 24, b: 36, period: 9 },
];

const IadPillDrift: React.FC<PrimitiveProps> = ({ fps, frame: box }) => {
  const frame = useCurrentFrame();
  const t = frame / fps;
  const s = Math.max(box.width / 1080, box.height / 1920);
  const ox = (box.width - 1080 * s) / 2;
  const oy = (box.height - 1920 * s) / 2;

  return (
    <AbsoluteFill style={{ background: PRIMARY, overflow: "hidden" }}>
      {SHAPES.map((sh, i) => {
        const k = Math.sin((t / sh.period) * Math.PI * 2);
        const round = sh.w === sh.h;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: ox + sh.x * s,
              top: oy + sh.y * s,
              width: sh.w * s,
              height: sh.h * s,
              borderRadius: 9999,
              background: sh.c,
              opacity: sh.o,
              transform: `translate(${k * sh.a * s}px, ${k * sh.b * s}px)${round ? "" : " rotate(-11deg)"}`,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default IadPillDrift;
